import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";
import { useState, useEffect } from "react";
import { API } from "../api/api";

export default function Home() {
  const nav = useNavigate();
  const [polls, setPolls] = useState([]);
  const [surveys, setSurveys] = useState([]);
  const [category, setCategory] = useState("all");

  useEffect(() => {
    fetchPolls();
    fetchSurveys();
  }, []);

  const fetchPolls = async () => {
    try {
      const res = await API.get("/polls");
      setPolls(res.data || []);
    } catch (err) { console.log("Poll error", err); }
  };

  const fetchSurveys = async () => {
    try {
      const res = await API.get("/surveys");
      setSurveys(res.data || []);
    } catch (err) { console.log("Survey error", err); }
  };

  return (
    <>
      <Navbar />

      <style>{`
        .home-container {
          min-height: 100vh;
          padding: 40px;
          color: white;
          background: #020617;
          background-image: 
            radial-gradient(circle at 10% 10%, rgba(249, 115, 22, 0.1) 0%, transparent 40%),
            radial-gradient(circle at 90% 90%, rgba(59, 130, 246, 0.1) 0%, transparent 40%);
          font-family: 'Inter', sans-serif;
        }

        /* NAVIGATION PILLS WITH ADD SIGN */
        .nav-pills {
          display: flex;
          justify-content: center;
          gap: 10px;
          margin: 30px auto;
        }

        .pill-group {
          display: flex;
          align-items: center;
          background: rgba(255, 255, 255, 0.05);
          border-radius: 30px;
          padding: 4px;
          border: 1px solid rgba(255, 255, 255, 0.1);
          transition: 0.3s;
        }

        .pill-group.active {
          background: rgba(59, 130, 246, 0.15);
          border-color: #3b82f6;
        }

        .pill-group button {
          padding: 6px 18px;
          border: none;
          background: transparent;
          color: #94a3b8;
          cursor: pointer;
          font-weight: 500;
        }

        .pill-group.active button { color: #60a5fa; }

        .add-icon {
          background: rgba(255, 255, 255, 0.1);
          width: 24px;
          height: 24px;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 14px;
          margin-right: 5px;
          color: white;
          cursor: pointer;
        }

        /* THE FLARE UP EFFECT */
        .glass-card {
          background: rgba(255, 255, 255, 0.02);
          backdrop-filter: blur(15px);
          border: 1px solid rgba(255, 255, 255, 0.1);
          border-radius: 28px;
          padding: 30px;
          transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
        }

        /* Orange Flare for Polls */
        .poll-card:hover {
          transform: scale(1.02);
          box-shadow: 0 0 40px rgba(249, 115, 22, 0.2);
          border-color: rgba(249, 115, 22, 0.5);
        }

        /* Blue React for Surveys */
        .survey-card:hover {
          transform: translateY(-10px);
          box-shadow: 0 15px 35px rgba(59, 130, 246, 0.2);
          border-color: rgba(59, 130, 246, 0.5);
        }

        /* POLL RESULTS UI */
        .poll-item {
          background: rgba(255, 255, 255, 0.03);
          border-radius: 12px;
          padding: 15px;
          margin-bottom: 15px;
        }

        .poll-question { margin-bottom: 10px; font-weight: 500; }

        .result-bar-bg {
          background: rgba(255, 255, 255, 0.1);
          height: 8px;
          border-radius: 10px;
          overflow: hidden;
          margin: 5px 0;
        }

        .result-bar-fill {
          height: 100%;
          background: linear-gradient(90deg, #f97316, #fb923c);
          transition: width 1s ease-in-out;
        }

        .dashboard-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
          gap: 40px;
          max-width: 1300px;
          margin: 0 auto;
        }
      `}</style>

      <div className="home-container">
        <div className="header-section" style={{textAlign:'center'}}>
          <h1 style={{fontSize: '2.5rem', fontWeight: '800'}}>Tek Surveys & Polls</h1>
          
          <div className="nav-pills">
            {["all", "student", "teacher", "general"].map(cat => (
              <div key={cat} className={`pill-group ${category === cat ? "active" : ""}`}>
                <button onClick={() => setCategory(cat)}>
                  {cat.toUpperCase()}
                </button>
                <div className="add-icon" title={`Add new to ${cat}`}>+</div>
              </div>
            ))}
          </div>
        </div>

        <div className="dashboard-grid">
          {/* POLLS WITH RESULTS */}
          <div className="glass-card poll-card">
            <h3 style={{color: '#f97316', letterSpacing: '2px', marginBottom: '20px'}}>🔥 LIVE POLLS</h3>
            {polls.slice(0, 2).map(p => (
              <div key={p._id} className="poll-item">
                <div className="poll-question">{p.question}</div>
                {/* Visual result mockup */}
                <div style={{fontSize: '11px', display: 'flex', justifyContent: 'space-between'}}>
                  <span>Success Rate</span>
                  <span>74%</span>
                </div>
                <div className="result-bar-bg">
                  <div className="result-bar-fill" style={{width: '74%'}}></div>
                </div>
              </div>
            ))}
            <button className="btn-action" style={{background: 'linear-gradient(45deg, #f97316, #ea580c)'}} onClick={() => nav("/create-poll")}>
              LAUNCH NEW POLL
            </button>
          </div>

          {/* SURVEYS WITH REACTION */}
          <div className="glass-card survey-card">
            <h3 style={{color: '#3b82f6', letterSpacing: '2px', marginBottom: '20px'}}>📋 RECENT SURVEYS</h3>
            {surveys
              .filter(s => category === "all" || (s.category || "").toLowerCase() === category)
              .slice(0, 3)
              .map(s => (
                <div key={s._id} className="item-row" onClick={() => nav(`/survey/${s._id}`)}>
                  <div>
                    <div style={{fontWeight:'bold'}}>{s.title}</div>
                    <div style={{fontSize:'10px', color:'#64748b'}}>{s.category || "General"}</div>
                  </div>
                  <span style={{color: '#60a5fa', fontSize: '12px'}}>TAKE ➜</span>
                </div>
              ))}
            <button className="btn-action" onClick={() => nav("/create-survey")}>
              START FEEDBACK
            </button>
          </div>
        </div>
      </div>
    </>
  );
}
